CREATE OR REPLACE FUNCTION public.pro_record_team_location(_visit uuid,_pro uuid,_action text,_lat numeric,_lng numeric,_reason text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF NOT public.is_service_caller() THEN RAISE EXCEPTION 'forbidden'; END IF; IF _action NOT IN ('check_in','check_out') OR _action IS NULL THEN RAISE EXCEPTION 'invalid_action'; END IF; result:=public.pro_gps_validate(_visit,_pro,_lat::double precision,_lng::double precision,_reason); IF NOT coalesce((result->>'ok')::boolean,false) THEN RAISE EXCEPTION '%',result->>'error'; END IF; PERFORM public.cleaning_team_presence_record(_visit,_pro,_action,_lat,_lng); IF _action='check_in' THEN UPDATE public.cleaning_team_presence SET check_in_location_reason=_reason WHERE visit_id=_visit AND pro_id=_pro; ELSE UPDATE public.cleaning_team_presence SET check_out_location_reason=_reason WHERE visit_id=_visit AND pro_id=_pro; END IF; END $$;
REVOKE ALL ON FUNCTION public.pro_record_team_location(uuid,uuid,text,numeric,numeric,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.pro_record_team_location(uuid,uuid,text,numeric,numeric,text) TO service_role;